"""Parsing and translation of the Melody pattern language.

The parser keeps source positions throughout, including the unsuccessful
alternatives, so that diagnostics point to the first useful place to edit.
"""
from dataclasses import dataclass
import re


ORDER = [
    'root', 'EOI', 'amount', 'literal', 'raw', 'symbol_identifier', 'not',
    'class_content', 'range', 'ascii_range_start', 'ascii_range_end',
    'quantifier_quantity', 'quantifier_range', 'some', 'any', 'option', 'over',
    'group_declaration', 'assertion_declaration', 'assertion_type',
    'variable_declaration', 'variable_invocation', 'block', 'identifier',
]
BASE = {'literal', 'raw', 'not', 'range', 'variable_invocation'}
OUTER = {'group_declaration', 'assertion_declaration', 'variable_declaration'}
CLASS_CHARS = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!#$%&*@\\^_')


class CompileError(Exception):
    pass


@dataclass
class Failure:
    pos: int
    expected: set

    def merge(self, other):
        if other is None or self.pos > other.pos:
            return self
        if other.pos > self.pos:
            return other
        return Failure(self.pos, self.expected | other.expected)


@dataclass
class Parsed:
    node: tuple
    end: int


def preprocess(text):
    """Normalize text lines and expand full-line comments."""
    lines = text.split('\n')
    if text.endswith('\n'):
        lines.pop()
    for i, line in enumerate(lines):
        if line.endswith('\r') and (i < len(lines)-1 or text.endswith('\n')):
            line = line[:-1]
        stripped = line.lstrip()
        if stripped.startswith('//'):
            line = '/*' + stripped[2:] + '*/'
        lines[i] = line
    return '\n'.join(lines)


def format_failure(source, failure):
    pos = min(failure.pos, len(source))
    line_no = source.count('\n', 0, pos) + 1
    start = source.rfind('\n', 0, pos) + 1
    end = source.find('\n', pos)
    if end < 0:
        end = len(source)
    line = source[start:end]
    col = pos-start+1
    prefix = ''.join('\t' if c == '\t' else ' ' for c in source[start:pos])
    width = len(str(line_no))
    names = sorted(failure.expected, key=lambda n: ORDER.index(n) if n in ORDER else len(ORDER))
    if len(names) == 1:
        expected = names[0]
    elif len(names) == 2:
        expected = ' or '.join(names)
    else:
        expected = ', '.join(names[:-1]) + ', or ' + names[-1]
    line = line.replace('\r', '␍')
    return (f" --> {line_no}:{col}\n{' '*width} |\n{line_no} | {line}\n"
            f"{' '*width} | {prefix}^---\n{' '*width} |\n"
            f"{' '*width} = expected {expected}")


class Parser:
    def __init__(self, source):
        self.s = source
        self.n = len(source)

    def skip(self, pos):
        while pos < self.n:
            if self.s[pos] in ' \t\n':
                pos += 1
            elif self.s.startswith('/*', pos):
                end = self.s.find('*/', pos+2)
                if end < 0:
                    break
                pos = end+2
            else:
                break
        return pos

    def word(self, value, pos):
        if self.s.startswith(value, pos):
            return self.skip(pos+len(value))
        return None

    def ident(self, pos, symbol=False):
        valid = lambda c: ('a' <= c <= 'z' or 'A' <= c <= 'Z' or c == '_' or (symbol and c == ':'))
        if pos >= self.n or not valid(self.s[pos]):
            return None
        end = pos+1
        # Whitespace is allowed between identifier characters.  The initial
        # separator belongs to a one-character identifier as well.
        end = self.skip(end)
        while end < self.n and valid(self.s[end]):
            end += 1
            next_pos = self.skip(end)
            if next_pos < self.n and valid(self.s[next_pos]):
                end = next_pos
            else:
                break
        return self.s[pos:end].strip(), end

    def amount(self, pos):
        m = re.match(r'[0-9]+', self.s[pos:])
        if not m:
            return None
        return m[0], pos+len(m[0])

    def string(self, pos, raw=False):
        if pos >= self.n or (self.s[pos] != '`' if raw else self.s[pos] not in "\"'"):
            return None
        delimiter = self.s[pos]
        end = pos+1
        pieces = []
        while end < self.n:
            c = self.s[end]
            if c == delimiter:
                return Parsed(('raw' if raw else 'literal', ''.join(pieces)), end+1)
            if c == '\\':
                if end+1 >= self.n:
                    return None
                nxt = self.s[end+1]
                if nxt == delimiter:
                    pieces.append(delimiter)
                    end += 2
                elif nxt == '\\':
                    pieces.append('\\\\')
                    end += 2
                elif not raw and nxt in 'nrtfb/':
                    pieces.append('\\'+nxt)
                    end += 2
                elif not raw and nxt == 'u' and re.fullmatch(r'[0-9a-fA-F]{4}', self.s[end+2:end+6] or ''):
                    pieces.append(self.s[end:end+6])
                    end += 6
                else:
                    return None
            else:
                if not raw and c in '.*+?^${}()|[]':
                    pieces.append('\\'+c)
                else:
                    pieces.append(c)
                end += 1
        return None

    def symbol(self, pos):
        if pos >= self.n or self.s[pos] != '<':
            return None, None
        start = self.skip(pos+1)
        ident = self.ident(start, symbol=True)
        if ident is None:
            return None, Failure(start, {'symbol_identifier'})
        name, end = ident
        end = self.skip(end)
        if end < self.n and self.s[end] == '>':
            return Parsed(('symbol', name, False), end+1), None
        return None, None

    def range(self, pos):
        """A numeric range, or a range with individual ASCII endpoints."""
        num = self.amount(pos)
        failure = None
        if num:
            left, end = num
            to = self.word('to', self.skip(end))
            if to is not None:
                right = self.amount(to)
                if right:
                    return Parsed(('range', left[0], right[0][0], False), right[1]), None, set()
                failure = Failure(to, {'amount'})
        else:
            failure = Failure(pos, {'amount'})
        if pos < self.n and ord(self.s[pos]) < 128:
            end = self.skip(pos+1)
            to = self.word('to', end)
            if to is not None:
                if to < self.n and ord(self.s[to]) < 128:
                    return Parsed(('range', self.s[pos], self.s[to], False), to+1), failure, ({'amount'} if not num else set())
                failure = (failure or Failure(to, set())).merge(Failure(to, {'ascii_range_end'}))
        else:
            failure = (failure or Failure(pos, set())).merge(Failure(pos, {'ascii_range_start'}))
        return None, failure, set()

    def class_content(self, pos):
        if pos >= self.n or self.s[pos] not in CLASS_CHARS:
            return None
        end = self.skip(pos+1)
        while end < self.n and self.s[end] in CLASS_CHARS:
            end += 1
            next_pos = self.skip(end)
            if next_pos < self.n and self.s[next_pos] in CLASS_CHARS:
                end = next_pos
            else:
                break
        return Parsed(('class', self.s[pos:end]), end)

    def negative(self, pos):
        start = self.word('not', pos)
        if start is None:
            return None, Failure(pos, {'not'})
        # Ranges take precedence over a list of characters.
        ranged, range_error, _ = self.range(start)
        symbol, sym_error = self.symbol(start)
        content = self.class_content(start)
        failure = Failure(start, set())
        if not self.amount(start):
            failure.expected.add('amount')
        if ranged:
            result = Parsed(('range', ranged.node[1], ranged.node[2], True), ranged.end)
        elif symbol:
            result = Parsed(('symbol', symbol.node[1], True), symbol.end)
        elif content:
            result = content
        else:
            result = None
            failure.expected.add('class_content')
            if start >= self.n or ord(self.s[start]) >= 128:
                failure.expected.add('ascii_range_start')
        if sym_error:
            failure = failure.merge(sym_error)
        if range_error and range_error.pos > start:
            failure = failure.merge(range_error)
        if result:
            end = self.skip(result.end)
            if end < self.n and self.s[end] == ';':
                return Parsed(result.node, end+1), None
        return None, failure

    def raw_statement(self, pos):
        """Try the semicolon-terminated alternatives and collect their errors."""
        expected = set()
        failure = Failure(pos, expected)
        literal = self.string(pos)
        if literal:
            result = literal
        else:
            expected.add('literal')
            negative, neg_error = self.negative(pos)
            if negative:
                return negative, None
            failure = failure.merge(neg_error)
            if neg_error.pos == pos:
                expected.add('not')
            ranged, range_error, range_expected = self.range(pos)
            if ranged:
                result = ranged
                expected.update(range_expected)
            else:
                # A quantity can partially match this alternative without
                # producing a useful character range.
                if self.amount(pos) is None:
                    expected.add('range')
                if range_error and range_error.pos > pos:
                    failure = failure.merge(range_error)
                raw = self.string(pos, raw=True)
                symbol, sym_error = self.symbol(pos)
                if raw or symbol:
                    result = raw or symbol
                else:
                    expected.add('raw')
                    if sym_error:
                        failure = failure.merge(sym_error)
                    result = None
                    if pos < self.n and self.s[pos] == '.':
                        start = self.skip(pos+1)
                        ident = self.ident(start)
                        if ident:
                            result = Parsed(('invoke', ident[0]), ident[1])
                        else:
                            failure = failure.merge(Failure(start, {'identifier'}))
                    else:
                        expected.add('variable_invocation')
        if result:
            end = self.skip(result.end)
            if end < self.n and self.s[end] == ';':
                return Parsed(result.node, end+1), None
        failure = failure.merge(Failure(pos, expected))
        return None, failure

    def quantity(self, pos):
        start = pos
        lazy = False
        after = self.word('lazy', pos)
        if after is not None:
            lazy = True
            pos = after
        base = pos
        num = self.amount(pos)
        failure = None
        kind = None
        values = ()
        if num:
            left, end = num
            to = self.word('to', self.skip(end))
            if to is not None:
                right = self.amount(to)
                if right:
                    kind, values, end = 'between', (left, right[0]), right[1]
                else:
                    return None, Failure(to, {'amount'})
            else:
                kind, values = 'exact', (left,)
                failure = Failure(base, {'quantifier_range'})
        else:
            for word in ('some', 'any', 'option'):
                end = self.word(word, pos)
                if end is not None:
                    kind = word
                    break
            if kind is None:
                end = self.word('over', pos)
                if end is not None:
                    num = self.amount(end)
                    if not num:
                        return None, Failure(end, {'amount'})
                    kind, values, end = 'over', (num[0],), num[1]
                else:
                    if lazy:
                        return None, Failure(pos, {'amount','some','any','option','over'})
                    return None, Failure(start, {'quantifier_quantity'})
        after = self.word('of', self.skip(end))
        if after is None:
            if kind == 'exact':
                return None, failure
            return None, Failure(start, {'quantifier_quantity'})
        return (kind, values, lazy, after), None

    def group(self, pos):
        for kind in ('match','capture','either'):
            after = self.word(kind, pos)
            if after is None:
                continue
            name = None
            extra = None
            if kind == 'capture':
                ident = self.ident(after)
                if ident:
                    name, after = ident
                    after = self.skip(after)
                else:
                    extra = Failure(after, {'identifier'})
            block, error = self.block(after)
            if block:
                return Parsed(('group', kind, name, block.node[1]), block.end), None
            if extra:
                error = error.merge(extra)
            return None, error
        return None, Failure(pos, {'group_declaration'})

    def assertion(self, pos):
        after = self.word('not', pos)
        neg = after is not None
        start = after if neg else pos
        for kind in ('ahead','behind'):
            after = self.word(kind, start)
            if after is not None:
                block, error = self.block(after)
                if block:
                    return Parsed(('assertion', kind, neg, block.node[1]), block.end), None
                return None, error
        return None, Failure(start, {'assertion_type'} if neg else {'assertion_declaration'})

    def declaration(self, pos):
        after = self.word('let', pos)
        if after is None or after >= self.n or self.s[after] != '.':
            return None, Failure(pos, {'variable_declaration'})
        start = self.skip(after+1)
        ident = self.ident(start)
        if not ident:
            return None, Failure(start, {'identifier'})
        name, after = ident
        after = self.skip(after)
        if after >= self.n or self.s[after] != '=':
            return None, Failure(pos, {'variable_declaration'})
        block, error = self.block(self.skip(after+1))
        if block:
            return Parsed(('declare', name, block.node[1]), block.end), None
        return None, error

    def statement(self, pos, quantified=True):
        result, failure = self.raw_statement(pos)
        if result:
            return result, None
        if quantified:
            quantity, error = self.quantity(pos)
            if quantity:
                kind, values, lazy, after = quantity
                child, error = self.statement(after, quantified=False)
                if child:
                    return Parsed(('quantifier', kind, values, lazy, child.node), child.end), None
            failure = failure.merge(error)
        for parser in (self.group, self.assertion, self.declaration):
            result, error = parser(pos)
            if result:
                return result, None
            failure = failure.merge(error)
        return None, failure

    def block(self, pos):
        if pos >= self.n or self.s[pos] != '{':
            return None, Failure(pos, {'block'})
        pos = self.skip(pos+1)
        nodes = []
        while True:
            result, error = self.statement(pos)
            if result:
                nodes.append(result.node)
                pos = self.skip(result.end)
            else:
                if nodes and pos < self.n and self.s[pos] == '}':
                    return Parsed(('block', nodes), pos+1), None
                return None, error

    def parse(self):
        pos = self.skip(0)
        nodes = []
        while pos < self.n:
            result, error = self.statement(pos)
            if result:
                nodes.append(result.node)
                pos = self.skip(result.end)
            else:
                error = error.merge(Failure(pos, {'EOI'}))
                if error.pos == 0:
                    error = Failure(0, {'root'})
                raise CompileError(format_failure(self.s, error))
        return nodes


SYMBOLS = {
    'char': '.', 'space': ' ', 'whitespace': r'\s', 'digit': r'\d',
    'word': r'\w', 'tab': r'\t', 'newline': r'\n', 'return': r'\r',
    'vertical': r'\v', 'feed': r'\f', 'null': r'\0', 'backspace': r'[\b]',
    'start': '^', 'end': '$', 'boundary': r'\b',
    'alphabetic': '[a-zA-Z]', 'alphanumeric': '[a-zA-Z0-9]',
}
NEGATIVE_SYMBOLS = {'word': r'\W', 'digit': r'\D', 'whitespace': r'\S', 'boundary': r'\B'}


def atom_count(regex):
    pos = 0
    count = 0
    while pos < len(regex):
        pos += 2 if regex[pos] == '\\' and pos+1 < len(regex) else 1
        count += 1
    return count


class Renderer:
    def __init__(self):
        self.variables = {}

    def sequence(self, nodes, separator=''):
        return separator.join(self.node(node) for node in nodes)

    def node(self, node):
        kind = node[0]
        if kind in ('literal','raw'):
            return node[1]
        if kind == 'symbol':
            _, name, neg = node
            if name not in SYMBOLS:
                raise CompileError('usage of an unrecognized symbol')
            value = SYMBOLS[name]
            if neg:
                if name in ('start','end','char'):
                    raise CompileError(f'negative {name} not allowed')
                if name in NEGATIVE_SYMBOLS:
                    return NEGATIVE_SYMBOLS[name]
                if value.startswith('['):
                    value = value[1:-1]
                return '[^'+value+']'
            return value
        if kind == 'range':
            return '[' + ('^' if node[3] else '') + node[1]+'-'+node[2]+']'
        if kind == 'class':
            return '[^'+node[1]+']'
        if kind == 'group':
            _, group_type, name, children = node
            body = self.sequence(children, '|' if group_type == 'either' else '')
            if group_type == 'capture':
                return ('(?<'+name+'>' if name is not None else '(') + body + ')'
            return '(?:'+body+')'
        if kind == 'assertion':
            _, direction, negative, children = node
            return '(?' + ('<' if direction == 'behind' else '') + ('!' if negative else '=') + self.sequence(children) + ')'
        if kind == 'declare':
            self.variables[node[1]] = self.sequence(node[2])
            return ''
        if kind == 'invoke':
            if node[1] not in self.variables:
                raise CompileError('usage of an uninitialized variable')
            return self.variables[node[1]]
        if kind == 'quantifier':
            _, quantity, amounts, lazy, child = node
            # Evaluate the child first; declarations and symbol errors have
            # the same semantics inside a repeated expression.
            body = self.node(child)
            if child[0] == 'assertion':
                raise CompileError('unexpected assertion in quantifier')
            if child[0] == 'invoke':
                raise CompileError('unexpected variable invocation in quantifier')
            if child[0] == 'declare':
                raise CompileError('unexpected skipped node in quantifier')
            if child[0] == 'symbol' and child[1] in ('start','end'):
                raise CompileError('unexpected special symbol in quantifier')
            if child[0] in ('literal','raw') and atom_count(body) != 1:
                body = '(?:'+body+')'
            if quantity == 'exact':
                suffix = '{'+amounts[0]+'}'
            elif quantity == 'between':
                a, b = amounts
                if len(a.lstrip('0')) > 20 or len(b.lstrip('0')) > 20 or int(a) > int(b) or int(b) > 18446744073709551615:
                    raise CompileError('usage of an invalid quantifier range')
                suffix = '{'+a+','+b+'}'
            elif quantity == 'over':
                a = amounts[0]
                if len(a.lstrip('0')) > 20 or int(a) >= 18446744073709551615:
                    raise CompileError('could not parse an amount')
                suffix = '{'+str(int(a)+1)+',}'
            else:
                suffix = {'some':'+','any':'*','option':'?'}[quantity]
            return body+suffix+('?' if lazy else '')
        raise CompileError('unexpected node')


def compile_pattern(source):
    prepared = preprocess(source)
    nodes = Parser(prepared).parse()
    return Renderer().sequence(nodes)
