"""A compact ECMAScript-style regular-expression reader and boolean matcher.

No external regex executable is used.  Character classes, assertions, groups,
backreferences and repetition are represented directly and evaluated with
backtracking.  This also lets the command line report regex syntax errors in a
consistent vocabulary, independent of a host interpreter's regex library.
"""
import re
import unicodedata


class RegexError(Exception):
    pass


SPACE = set('\t\n\v\f\r \u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff')
LINES = set('\n\r\u2028\u2029')


def isword(c):
    return bool(c) and ('a' <= c <= 'z' or 'A' <= c <= 'Z' or '0' <= c <= '9' or c == '_')


def name_start(c):
    return c in '_$' or unicodedata.category(c) in ('Lu','Ll','Lt','Lm','Lo','Nl')


def name_part(c):
    return name_start(c) or c in '\u200c\u200d' or unicodedata.category(c) in ('Mn','Mc','Nd','Pc')


class RegexParser:
    def __init__(self, pattern):
        self.s = pattern
        self.pos = 0
        self.n = len(pattern)
        self.captures = 0
        self.names = {}
        self.references = []

    def peek(self):
        return self.s[self.pos] if self.pos < self.n else ''

    def parse(self):
        node = self.choice()
        if self.pos < self.n:
            raise RegexError('unbalanced parenthesis')
        for name in self.references:
            if name not in self.names:
                raise RegexError('invalid named capture referenced')
        return node

    def choice(self):
        branches = [self.sequence()]
        while self.peek() == '|' and self.pos < self.n:
            self.pos += 1
            branches.append(self.sequence())
        return branches[0] if len(branches) == 1 else ('or', branches)

    def braced(self):
        m = re.match(r'\{([0-9]+)(?:,([0-9]*))?\}', self.s[self.pos:])
        if not m:
            return None
        a = int(m[1]) if len(m[1]) < 1000 else 10**100
        b = a if m[2] is None else (int(m[2]) if m[2] and len(m[2]) < 1000 else (None if not m[2] else 10**100))
        if b is not None and a > b:
            raise RegexError('invalid quantifier')
        return a, b, len(m[0])

    def sequence(self):
        nodes = []
        while self.pos < self.n and self.peek() not in ')|':
            ch = self.peek()
            if ch in '*+?':
                raise RegexError('invalid atom character')
            if ch == '{' and self.braced():
                raise RegexError('invalid braced quantifier')
            node = self.atom()
            q = self.peek()
            bounds = None
            if self.pos < self.n and q in '*+?':
                bounds = {'*':(0,None), '+':(1,None), '?':(0,1)}[q]
                self.pos += 1
            elif q == '{':
                braced = self.braced()
                if braced:
                    bounds = braced[:2]
                    self.pos += braced[2]
            if bounds is not None:
                if node[0] in ('begin','end','boundary') or (node[0] == 'look' and node[2] == 'behind'):
                    raise RegexError('quantifier not allowed here')
                lazy = self.peek() == '?' and self.pos < self.n
                if lazy:
                    self.pos += 1
                node = ('repeat', node, bounds[0], bounds[1], lazy)
            nodes.append(node)
        if not nodes:
            return ('empty',)
        return nodes[0] if len(nodes) == 1 else ('seq', nodes)

    def atom(self):
        c = self.peek()
        self.pos += 1
        if c == '.':
            return ('dot',)
        if c == '^':
            return ('begin',)
        if c == '$':
            return ('end',)
        if c == '[':
            return self.char_class()
        if c == '\\':
            return self.escape(False)
        if c == '(':
            group = None
            if self.peek() == '?':
                self.pos += 1
                if self.peek() == ':':
                    self.pos += 1
                    group = ('plain',)
                elif self.peek() in ('=','!'):
                    neg = self.peek() == '!'
                    self.pos += 1
                    group = ('look', neg, 'ahead')
                elif self.s.startswith('<=', self.pos) or self.s.startswith('<!', self.pos):
                    neg = self.s[self.pos+1] == '!'
                    self.pos += 2
                    group = ('look', neg, 'behind')
                elif self.peek() == '<':
                    self.pos += 1
                    start = self.pos
                    while self.pos < self.n and self.peek() != '>':
                        self.pos += 1
                    name = self.s[start:self.pos]
                    if self.pos >= self.n or not name or not name_start(name[0]) or any(not name_part(c) for c in name[1:]):
                        raise RegexError('invalid token at named capture group identifier')
                    self.pos += 1
                    if name in self.names:
                        raise RegexError('duplicate capture group name')
                    self.captures += 1
                    self.names[name] = self.captures
                    group = ('group', self.captures)
                else:
                    raise RegexError('invalid token at named capture group identifier')
            if group is None:
                self.captures += 1
                group = ('group', self.captures)
            body = self.choice()
            if self.peek() != ')' or self.pos >= self.n:
                raise RegexError('unbalanced parenthesis')
            self.pos += 1
            if group[0] == 'plain':
                return ('plain', body)
            if group[0] == 'look':
                return group + (body,)
            return ('group', group[1], body)
        return ('lit', c)

    def escape(self, in_class):
        if self.pos >= self.n:
            raise RegexError('invalid escape at end of pattern')
        c = self.peek()
        self.pos += 1
        if c in 'dDsSwW':
            return ('type', c)
        if c in 'bB' and not in_class:
            return ('boundary', c == 'B')
