        if c in mapped:
            return ('lit', mapped[c])
        if c in 'xu':
            length = 2 if c == 'x' else 4
            digits = self.s[self.pos:self.pos+length]
            if len(digits) == length and re.fullmatch('[0-9a-fA-F]+', digits):
                self.pos += length
                return ('lit', chr(int(digits,16)))
            return ('lit', c)
        if c == 'c':
            if self.pos < self.n and ('a' <= self.peek() <= 'z' or 'A' <= self.peek() <= 'Z' or (in_class and self.peek() in '_0123456789')):
