                self.pos += 1
                return ('lit', value)
            self.pos -= 1
            return ('lit', '\\')
        if '0' <= c <= '9':
            if c != '0' and not in_class:
                digits = c
                while self.pos < self.n and '0' <= self.peek() <= '9':
                    digits += self.peek()
                    self.pos += 1
                return ('numref', digits)
            if c in '01234567':
                digits = c
                while self.pos < self.n and len(digits) < (3 if c < '4' else 2) and self.peek() in '01234567':
                    digits += self.peek()
                    self.pos += 1
                return ('lit', chr(int(digits,8)))
            return ('lit', c)
        if c == 'k' and not in_class and self.peek() == '<':
            self.pos += 1
            start = self.pos
            while self.pos < self.n and self.peek() != '>':
                self.pos += 1
            if self.pos >= self.n:
                raise RegexError('invalid named capture referenced')
            name = self.s[start:self.pos]
            self.pos += 1
            self.references.append(name)
            return ('ref', name)
        return ('lit', c)

    def class_item(self):
        c = self.peek()
        self.pos += 1
        if c == '\\':
            return self.escape(True)
        return ('lit', c)

    def char_class(self):
        neg = self.peek() == '^'
        if neg:
            self.pos += 1
        items = []
        while self.pos < self.n and self.peek() != ']':
            left = self.class_item()
            if self.peek() == '-' and self.pos+1 < self.n and self.s[self.pos+1] != ']':
