            yield from self.sequence(nodes, index+1, end, state)

    def repetition(self, node, pos, caps):
        _, body, lower, upper, lazy = node
        # The overwhelmingly common case can be evaluated without a stack.
        if body[0] in ('lit','dot','type','class'):
            end = pos
            limit = self.n if upper is None else min(self.n, pos+upper)
            while end < limit and accepts(body, self.text[end]):
                end += 1
            if end-pos < lower:
                return
            lengths = range(pos+lower,end+1) if lazy else range(end,pos+lower-1,-1)
            for end in lengths:
                yield end, caps
            return
        # Stack entries distinguish a yielded state from one whose children
        # still need to be considered.  This preserves greedy/lazy ordering.
        stack = [('visit', pos, caps, 0)]
        while stack:
            action, here, state, count = stack.pop()
            if action == 'yield':
                yield here, state
                continue
            choices = []
            if upper is None or count < upper:
                for end, next_caps in self.match(body, here, state):
                    if end == here:
                        if count < lower:
                            choices.append(('yield', end, next_caps, lower))
                        elif count == 0 and lower == 0:
                            # Repeating an empty atom can be omitted.
                            pass
                    else:
                        choices.append(('visit', end, next_caps, count+1))
            ready = [('yield', here, state, count)] if count >= lower else []
            ordered = ready+choices if lazy else choices+ready
            stack.extend(reversed(ordered))

    def match(self, node, pos, caps):
        self.steps += 1
        if self.steps > 2000000:
            return
        kind = node[0]
        if kind in ('lit','dot','type','class'):
            if pos < self.n and accepts(node, self.text[pos]):
                yield pos+1, caps
        elif kind == 'empty':
            yield pos, caps
        elif kind == 'seq':
            yield from self.sequence(node[1], 0, pos, caps)
        elif kind == 'or':
            for branch in node[1]:
                yield from self.match(branch, pos, caps)
        elif kind == 'plain':
            yield from self.match(node[1], pos, caps)
        elif kind == 'group':
            for end, state in self.match(node[2], pos, caps):
                updated = state.copy()
                updated[node[1]] = self.text[pos:end]
                yield end, updated
        elif kind == 'repeat':
            yield from self.repetition(node, pos, caps)
        elif kind == 'begin':
            if pos == 0:
                yield pos, caps
        elif kind == 'end':
            if pos == self.n:
                yield pos, caps
        elif kind == 'boundary':
            boundary = isword(self.text[pos-1] if pos else '') != isword(self.text[pos] if pos < self.n else '')
            if boundary != node[1]:
                yield pos, caps
        elif kind in ('ref','numref'):
            if kind == 'ref':
                number = self.names.get(node[1],0)
                value = caps.get(number,'')
            else:
                number = int(node[1])
                if number <= self.capture_count:
                    value = caps.get(number,'')
                else:
                    octal = re.match(r'[0-7]{1,3}', node[1])
                    if octal:
                        digits = octal[0]
                        if digits[0] >= '4':
                            digits = digits[:2]
                        value = chr(int(digits,8))+node[1][len(digits):]
                    else:
                        value = node[1]
            if self.text.startswith(value,pos):
                yield pos+len(value),caps
        elif kind == 'look':
            neg, direction, body = node[1:]
            found = None
            if direction == 'ahead':
                found = next(self.match(body,pos,caps),None)
            else:
                for start in range(pos,-1,-1):
                    for end, state in self.match(body,start,caps):
                        if end == pos:
                            found = end,state
                            break
                    if found is not None:
                        break
            if neg:
                if found is None:
                    yield pos,caps
            elif found is not None:
                yield pos,found[1]

    def search(self, text):
        self.text = text
        self.n = len(text)
        self.steps = 0
        for start in range(len(text)+1):
            if next(self.match(self.root,start,{}),None) is not None:
                return True
        return False
