"""Command line and interactive front ends for the pattern compiler."""
import os
import re
import sys
from .compiler import compile_pattern, CompileError
from .regex import Regex, RegexError
from .completions import generate


VERSION = '0.20.0'
FLAGS = {
    'output': ('o', 'OUTPUT_FILE_PATH'),
    'no-color': ('n', None),
    'repl': ('r', None),
    'generate-completions': ('', 'completions'),
    'test': ('t', 'test'),
    'test-file': ('f', 'test-file'),
    'help': ('h', None),
    'version': ('V', None),
}
SHORT = {short: name for name, (short, _) in FLAGS.items() if short}
CONFLICTS = {
    'output': {'test','test-file','generate-completions'},
    'repl': {'test','test-file','generate-completions'},
    'generate-completions': {'input','output','repl','test','test-file'},
    'test': {'output','repl','generate-completions','test-file'},
    'test-file': {'output','repl','generate-completions','test'},
    'input': {'generate-completions'},
}


def flag_description(name):
    if name == 'input':
        return '[INPUT_FILE_PATH]'
    argument = FLAGS[name][1]
    return '--'+name+(' <'+argument+'>' if argument else '')


def colored_enabled(disable=False):
    if disable:
        return False
    force = os.environ.get('CLICOLOR_FORCE')
    if force is not None and force != '0':
        return True
    if 'NO_COLOR' in os.environ or os.environ.get('CLICOLOR') == '0':
        return False
    return sys.stdout.isatty()


def clap_color(stream):
    if 'NO_COLOR' in os.environ or os.environ.get('TERM') == 'dumb':
        return False
    if os.environ.get('CLICOLOR_FORCE') not in (None,'0'):
        return True
    if os.environ.get('CLICOLOR') == '0':
        return False
    return stream.isatty()


def paint(s, color, enabled):
    return '\x1b['+color+'m'+s+'\x1b[0m' if enabled else s


def help_text(program, color=False):
    text = f'''A CLI wrapping the Melody language compiler

Usage: {program} [OPTIONS] [INPUT_FILE_PATH]

Arguments:
  [INPUT_FILE_PATH]  Read from a file
                     Use '-' and or pipe input to read from stdin

Options:
  -o, --output <OUTPUT_FILE_PATH>           Write to a file
  -n, --no-color                            Print output with no color
  -r, --repl                                Start the Melody REPL
      --generate-completions <completions>  Outputs completions for the selected shell
                                            To use, write the output to the appropriate location for your shell
  -t, --test <test>                         Test the compiled regex against a string
  -f, --test-file <test-file>               Test the compiled regex against the contents of a file
  -h, --help                                Print help
  -V, --version                             Print version
'''
    if color:
        for header in ('Usage:','Arguments:','Options:'):
            text = text.replace(header, '\x1b[1m\x1b[4m'+header+'\x1b[0m')
        text = text.replace(' '+program+' [OPTIONS]', ' '+paint(program,'1',True)+' [OPTIONS]')
        lines = text.splitlines(True)
        for i,line in enumerate(lines):
            if line.startswith('  -') or line.startswith('      --'):
                lines[i] = re.sub(r'--[a-z-]+|-[onrtfhV]', lambda m: paint(m[0],'1',True), line)
        text = ''.join(lines)
    return text


class CliError(Exception):
    def __init__(self, text):
        self.text = text


def jaro_winkler(a, b):
    if a == b:
        return 1.0
    radius = max(max(len(a),len(b))//2-1,0)
    am, bm = [False]*len(a), [False]*len(b)
    matches = 0
    for i,c in enumerate(a):
        for j in range(max(0,i-radius),min(len(b),i+radius+1)):
            if not bm[j] and c == b[j]:
                am[i] = bm[j] = True
                matches += 1
                break
    if not matches:
        return 0.0
    ac = [a[i] for i in range(len(a)) if am[i]]
    bc = [b[j] for j in range(len(b)) if bm[j]]
    transpositions = sum(x != y for x,y in zip(ac,bc))/2
    score = (matches/len(a)+matches/len(b)+(matches-transpositions)/matches)/3
    prefix = 0
    for x,y in zip(a,b):
        if x != y or prefix == 4:
            break
        prefix += 1
    return score+prefix*.1*(1-score) if score > .7 else score


class Arguments:
    def __init__(self, program):
        self.program = program
        self.options = {}
        self.order = []

    def usage(self, selected=None, group=False):
        if group:
            names = ['INPUT_FILE_PATH']+[flag_description(name) for name in list(FLAGS)[:6]]
            return 'Usage: '+self.program+' <'+'|'.join(names)+'>'
        if selected is None:
            return 'Usage: '+self.program+' [OPTIONS] [INPUT_FILE_PATH]'
        pieces = [flag_description(name) for name in selected if name != 'input']
        return 'Usage: '+self.program+(' '+' '.join(pieces) if pieces else '')+' [INPUT_FILE_PATH]'

    def error(self, message, usage=None, tip=None, no_usage=False):
        text = 'error: '+message+'\n\n'
        if tip:
            text += '  tip: '+tip+'\n\n'
        if not no_usage:
            text += (usage or self.usage())+'\n\n'
        text += "For more information, try '--help'.\n"
        raise CliError(text)

    def unknown(self, arg):
        suggestion = None
        if arg.startswith('--'):
            name = arg[2:].split('=',1)[0]
            scores = [(jaro_winkler(name, long),long) for long in FLAGS]
            score, best = max(scores)
            if score > .8:
                suggestion = best
        group = bool(suggestion or any(name != 'input' for name in self.order))
        if suggestion:
            tip = "a similar argument exists: '--"+suggestion+"'"
        elif arg.startswith('-') and arg != '-':
            tip = "to pass '"+arg+"' as a value, use '-- "+arg+"'"
        else:
            tip = None
            group = False
        self.error("unexpected argument '"+arg+"' found", self.usage(group=group), tip)

    def insert(self, name, value):
        if name in self.options:
            self.error("the argument '"+flag_description(name)+"' cannot be used multiple times")
        self.order.append(name)
        self.options[name] = value

    def check_conflicts(self):
        for name in self.order:
            others = [other for other in self.order if other in CONFLICTS.get(name,set())]
            if not others:
                continue
            lead = "the argument '"+flag_description(name)+"' cannot be used with"
            if len(others) == 1:
                message = lead+" '"+flag_description(others[0])+"'"
            else:
                message = lead+':\n'+'\n'.join('  '+flag_description(other) for other in others)
            selected = [x for x in self.order if x not in others]
            self.error(message, self.usage(selected))

    def parse(self, args):
        index = 0
        literal = False
        while index < len(args):
            arg = args[index]
            index += 1
            if not literal and arg == '--':
                literal = True
                continue
            if literal or not arg.startswith('-') or arg == '-':
                if 'input' in self.options:
                    self.unknown(arg)
                self.insert('input',arg)
                continue
            pending = []
            if arg.startswith('--'):
                name, equal, value = arg[2:].partition('=')
                if name not in FLAGS:
                    self.unknown('--'+name)
                pending.append((name, value if equal else None, bool(equal)))
            else:
                letters = arg[1:]
                offset = 0
                while offset < len(letters):
                    c = letters[offset]
                    if c not in SHORT:
                        self.unknown('-'+c)
                    name = SHORT[c]
                    offset += 1
                    if FLAGS[name][1] is not None:
                        rest = letters[offset:]
                        pending.append((name,rest.lstrip('=') if rest.startswith('=') else (rest or None),bool(rest)))
                        break
                    pending.append((name,None,False))
                    # Help and version stop short-option processing immediately.
                    if name in ('help','version'):
                        break
            for name,value,explicit in pending:
                if FLAGS[name][1] is None:
                    if explicit:
                        self.error("unexpected value '"+value+"' for '--"+name+"' found; no more were expected", self.usage(group=bool(self.order)) if self.order else self.usage([name]))
                    if name == 'help':
                        return 'help'
                    if name == 'version':
                        return 'version'
                    self.insert(name,True)
                    continue
                if value is None:
                    if index >= len(args) or (args[index].startswith('-') and args[index] != '-'):
                        if index < len(args) and args[index] != '--':
                            nextarg = args[index]
                            if nextarg.startswith('--') and nextarg[2:].split('=',1)[0] not in FLAGS:
                                self.unknown(nextarg.split('=',1)[0])
                            if nextarg.startswith('-') and not nextarg.startswith('--') and len(nextarg)>1 and nextarg[1] not in SHORT:
                                self.unknown('-'+nextarg[1])
                        self.error("a value is required for '"+flag_description(name)+"' but none was supplied",no_usage=True)
                    value = args[index]
                    index += 1
                self.insert(name,value)
        self.check_conflicts()
        return None


def app_error(message, color):
    sys.stderr.write(paint('Error: '+message,'91',color)+'\n')


REPL_COMMANDS = [
    (':u, :undo','undo the latest line'),
    (':r, :redo','redo the latest undo'),
    (':c, :clear','clear all REPL history and previous input'),
    (':s, :source','print all previously entered lines'),
    (':e, :exit','exit the REPL'),
]


def rust_debug(s):
    escaped = s.replace('\\','\\\\').replace('"','\\"').replace('\n','\\n').replace('\r','\\r').replace('\t','\\t').replace('\0','\\0')
    return '"'+escaped+'"'


def repl(color):
    out = sys.stdout
    out.write(paint('Melody REPL v'+VERSION,'92',color)+'\n\n'+paint('Commands:','92',color)+'\n\n')
    for commands,description in REPL_COMMANDS:
        out.write('- '+paint(commands,'94',color)+' - '+paint(description,'92',color)+'\n')
    out.write('\n')
    lines = []
    redo = []
    while True:
        out.write(paint('~ ','94',color));out.flush()
        line = sys.stdin.readline()
        line = line.rstrip('\n').rstrip('\r')
        if line.startswith(':'):
            if line in (':e',':exit'):
                out.write(paint('exit','92',color)+'\n');out.flush()
                return 0
            if line in (':s',':source'):
                if not lines:
                    out.write(paint('no lines to print\n','91',color))
                else:
                    out.write(paint('source','92',color)+'\n')
                    for number,src in enumerate(lines,1):
                        out.write(paint(str(number),'2',color)+' '+paint(src,'94',color)+'\n')
            elif line in (':u',':undo'):
                if not lines:
                    out.write(paint('nothing to undo\n','91',color))
                else:
                    redo.append(lines.pop())
                    out.write(paint('undo','92',color)+'\n')
                    if lines:
                        out.write(paint(compile_pattern('\n'.join(lines)),'94',color)+'\n')
            elif line in (':r',':redo'):
                if not redo:
                    out.write(paint('nothing to redo\n','91',color))
                else:
                    lines.append(redo.pop())
                    out.write(paint('redo','92',color)+'\n')
                    out.write(paint(compile_pattern('\n'.join(lines)),'94',color)+'\n')
            elif line in (':c',':clear'):
                lines.clear();redo.clear()
                out.write(paint('clear','92',color)+'\n')
            else:
                out.write(paint('Error:','91',color)+' '+paint('unrecognized command','91',color)+' '+paint(rust_debug(line),'94',color)+'\n')
        else:
            candidate = lines+([line] if line else [])
            try:
                compiled = compile_pattern('\n'.join(candidate))
                if line:
                    lines.append(line)
                    redo.clear()
                out.write(paint(compiled,'94',color)+'\n')
            except CompileError as error:
                app_error(str(error),color)
        out.write('\n');out.flush()


def main(argv=None):
    argv = sys.argv if argv is None else argv
    program = os.path.basename(argv[0]) or 'executable'
    args = Arguments(program)
    try:
        action = args.parse(argv[1:])
    except CliError as error:
        sys.stderr.write(error.text)
        return 2
    if action == 'help':
        sys.stdout.write(help_text(program, clap_color(sys.stdout)))
        return 0
    if action == 'version':
        sys.stdout.write('melody_cli '+VERSION+'\n')
        return 0
    options = args.options
    color = colored_enabled(bool(options.get('no-color')))
    if 'generate-completions' in options:
        shell = options['generate-completions']
        output = generate(shell)
        if output is None:
            sys.stderr.write("Unknown or unsupported shell: '"+shell+"'\nTry one of: 'bash', 'zsh', 'fish', 'elvish', 'powershell'\n\n")
        else:
            sys.stdout.write(output)
        return 0
    if options.get('repl'):
        if not sys.stdin.isatty() or not sys.stdout.isatty():
            app_error('repl argument supplied with piped input or output',color)
            return 64
        return repl(color)
    path = options.get('input')
    if path is not None and path != '-':
        try:
            with open(path,'rb') as source:
                text = source.read().decode('utf-8')
        except (OSError, UnicodeError, ValueError):
            app_error('unable read file at path '+path,color)
            return 65
    elif not sys.stdin.isatty():
        try:
            text = sys.stdin.buffer.read().decode('utf-8')
        except (OSError, UnicodeError):
            app_error('unable to read stdin',color)
            return 65
    else:
        message = "No input file supplied and no input piped\nTry adding a path argument: 'melody ./file.mdy'"
        sys.stderr.write(paint(message,'94',color)+'\n')
        sys.stdout.write('\n'+help_text('melody_cli',clap_color(sys.stdout)))
        return 66
    try:
        compiled = compile_pattern(text)
    except CompileError as error:
        app_error(str(error),color)
        return 65
    if 'test' in options or 'test-file' in options:
        if 'test-file' in options:
            path = options['test-file']
            try:
                with open(path,'rb') as test_file:
                    subject = test_file.read().decode('utf-8')
            except (OSError, UnicodeError, ValueError):
                app_error('unable read file at path '+path,color)
                return 74
            label = path
        else:
            subject = options['test']
            label = "'"+subject+"'"
        try:
            expression = Regex(compiled)
        except RegexError as error:
            app_error('could not compile regex\nCause: '+str(error)+'\nRegex: '+compiled,color)
            return 65
        matched = expression.search(subject)
        sys.stdout.write(label+' '+paint('matched' if matched else 'did not match','92' if matched else '91',color)+'\n')
    elif 'output' in options:
        path = options['output']
        try:
            with open(path,'wb') as output:
                output.write(compiled.encode('utf-8'))
        except (OSError, ValueError):
            app_error(path,color)
            return 74
    else:
        sys.stdout.write(paint(compiled,'94',color)+'\n')
    return 0


def entrypoint():
    try:
        sys.exit(main())
    except BrokenPipeError:
        os._exit(0)
