    if 'NO_COLOR' in os.environ or os.environ.get('TERM') == 'dumb':
        return False
    if os.environ.get('CLICOLOR_FORCE') not in (None,'0'):
        return True
    if os.environ.get('CLICOLOR') == '0':
        return False
    return stream.isatty()


