        lines = text.splitlines(True)
        for i,line in enumerate(lines):
            if line.startswith('  -') or line.startswith('      --'):
                lines[i] = re.sub(r'--[a-z-]+|-[onrtfhV]', lambda m: paint(m[0],'1',True), line)
