def jaro_winkler(a, b):
    if a == b:
        return 1.0
    radius = max(max(len(a),len(b))//2-1,0)
    am, bm = [False]*len(a), [False]*len(b)
    matches = 0
    for i,c in enumerate(a):
        for j in range(max(0,i-radius),min(len(b),i+radius+1)):
            if not bm[j] and c == b[j]:
                am[i] = bm[j] = True
                matches += 1
                break
    if not matches:
        return 0.0
    ac = [a[i] for i in range(len(a)) if am[i]]
    bc = [b[j] for j in range(len(b)) if bm[j]]
    transpositions = sum(x != y for x,y in zip(ac,bc))/2
    score = (matches/len(a)+matches/len(b)+(matches-transpositions)/matches)/3
    prefix = 0
    for x,y in zip(a,b):
        if x != y or prefix == 4:
