            return 'Usage: '+self.program+' <'+'|'.join(names)+'>'
        if selected is None:
            return 'Usage: '+self.program+' [OPTIONS] [INPUT_FILE_PATH]'
        pieces = [flag_description(name) for name in selected if name != 'input']
        return 'Usage: '+self.program+(' '+' '.join(pieces) if pieces else '')+' [INPUT_FILE_PATH]'

    def error(self, message, usage=None, tip=None, no_usage=False):
        text = 'error: '+message+'\n\n'
        if tip:
            text += '  tip: '+tip+'\n\n'
        if not no_usage:
            text += (usage or self.usage())+'\n\n'
        text += "For more information, try '--help'.\n"
        raise CliError(text)

    def unknown(self, arg):
        suggestion = None
        if arg.startswith('--'):
            name = arg[2:].split('=',1)[0]
            scores = [(jaro_winkler(name, long),long) for long in FLAGS]
            score, best = max(scores)
            if score > .8:
                suggestion = best
        group = bool(suggestion or any(name != 'input' for name in self.order))
        if suggestion:
            tip = "a similar argument exists: '--"+suggestion+"'"
        elif arg.startswith('-') and arg != '-':
            tip = "to pass '"+arg+"' as a value, use '-- "+arg+"'"
        else:
            tip = None
            group = False
        self.error("unexpected argument '"+arg+"' found", self.usage(group=group), tip)

    def insert(self, name, value):
