        for name in self.order:
            others = [other for other in self.order if other in CONFLICTS.get(name,set())]
            if not others:
                continue
            lead = "the argument '"+flag_description(name)+"' cannot be used with"
            if len(others) == 1:
                message = lead+" '"+flag_description(others[0])+"'"
            else:
                message = lead+':\n'+'\n'.join('  '+flag_description(other) for other in others)
            selected = [x for x in self.order if x not in others]
