def repl(color):
    out = sys.stdout
    out.write(paint('Melody REPL v'+VERSION,'92',color)+'\n\n'+paint('Commands:','92',color)+'\n\n')
    for commands,description in REPL_COMMANDS:
        out.write('- '+paint(commands,'94',color)+' - '+paint(description,'92',color)+'\n')
    out.write('\n')
    lines = []
    redo = []
    while True:
        out.write(paint('~ ','94',color));out.flush()
        line = sys.stdin.readline()
        line = line.rstrip('\n').rstrip('\r')
        if line.startswith(':'):
            if line in (':e',':exit'):
                out.write(paint('exit','92',color)+'\n');out.flush()
                return 0
            if line in (':s',':source'):
                if not lines:
                    out.write(paint('no lines to print\n','91',color))
                else:
                    out.write(paint('source','92',color)+'\n')
                    for number,src in enumerate(lines,1):
                        out.write(paint(str(number),'2',color)+' '+paint(src,'94',color)+'\n')
            elif line in (':u',':undo'):
                if not lines:
                    out.write(paint('nothing to undo\n','91',color))
                else:
                    redo.append(lines.pop())
                    out.write(paint('undo','92',color)+'\n')
                    if lines:
                        out.write(paint(compile_pattern('\n'.join(lines)),'94',color)+'\n')
            elif line in (':r',':redo'):
                if not redo:
                    out.write(paint('nothing to redo\n','91',color))
                else:
                    lines.append(redo.pop())
                    out.write(paint('redo','92',color)+'\n')
                    out.write(paint(compile_pattern('\n'.join(lines)),'94',color)+'\n')
            elif line in (':c',':clear'):
                lines.clear();redo.clear()
                out.write(paint('clear','92',color)+'\n')
            else:
                out.write(paint('Error:','91',color)+' '+paint('unrecognized command','91',color)+' '+paint(rust_debug(line),'94',color)+'\n')
        else:
            candidate = lines+([line] if line else [])
            try:
                compiled = compile_pattern('\n'.join(candidate))
                if line:
                    lines.append(line)
                    redo.clear()
                out.write(paint(compiled,'94',color)+'\n')
            except CompileError as error:
                app_error(str(error),color)
        out.write('\n');out.flush()


def main(argv=None):
    argv = sys.argv if argv is None else argv
    program = os.path.basename(argv[0]) or 'executable'
    args = Arguments(program)
    try:
        action = args.parse(argv[1:])
    except CliError as error:
        sys.stderr.write(error.text)
        return 2
    if action == 'help':
        sys.stdout.write(help_text(program, clap_color(sys.stdout)))
        return 0
    if action == 'version':
        sys.stdout.write('melody_cli '+VERSION+'\n')
        return 0
    options = args.options
    color = colored_enabled(bool(options.get('no-color')))
    if 'generate-completions' in options:
        shell = options['generate-completions']
        output = generate(shell)
        if output is None:
            sys.stderr.write("Unknown or unsupported shell: '"+shell+"'\nTry one of: 'bash', 'zsh', 'fish', 'elvish', 'powershell'\n\n")
        else:
            sys.stdout.write(output)
        return 0
    if options.get('repl'):
        if not sys.stdin.isatty() or not sys.stdout.isatty():
            app_error('repl argument supplied with piped input or output',color)
            return 64
        return repl(color)
    path = options.get('input')
    if path is not None and path != '-':
        try:
            with open(path,'rb') as source:
                text = source.read().decode('utf-8')
        except (OSError, UnicodeError, ValueError):
            app_error('unable read file at path '+path,color)
            return 65
    elif not sys.stdin.isatty():
        try:
            text = sys.stdin.buffer.read().decode('utf-8')
        except (OSError, UnicodeError):
            app_error('unable to read stdin',color)
            return 65
    else:
        message = "No input file supplied and no input piped\nTry adding a path argument: 'melody ./file.mdy'"
        sys.stderr.write(paint(message,'94',color)+'\n')
        sys.stdout.write('\n'+help_text('melody_cli',clap_color(sys.stdout)))
        return 66
    try:
        compiled = compile_pattern(text)
    except CompileError as error:
        app_error(str(error),color)
        return 65
    if 'test' in options or 'test-file' in options:
        if 'test-file' in options:
            path = options['test-file']
            try:
                with open(path,'rb') as test_file:
                    subject = test_file.read().decode('utf-8')
            except (OSError, UnicodeError, ValueError):
                app_error('unable read file at path '+path,color)
                return 74
            label = path
        else:
            subject = options['test']
            label = "'"+subject+"'"
        try:
            expression = Regex(compiled)
        except RegexError as error:
            app_error('could not compile regex\nCause: '+str(error)+'\nRegex: '+compiled,color)
            return 65
        matched = expression.search(subject)
        sys.stdout.write(label+' '+paint('matched' if matched else 'did not match','92' if matched else '91',color)+'\n')
    elif 'output' in options:
        path = options['output']
        try:
            with open(path,'wb') as output:
                output.write(compiled.encode('utf-8'))
        except (OSError, ValueError):
            app_error(path,color)
            return 74
    else:
        sys.stdout.write(paint(compiled,'94',color)+'\n')
    return 0


def entrypoint():
    try:
        sys.exit(main())
    except BrokenPipeError:
        os._exit(0)
