#!/usr/bin/env python3
"""Build the standalone executable using only the Python standard library."""
from pathlib import Path
import sys
import zipfile
import os

root = Path(__file__).resolve().parent
output = Path(sys.argv[1]) if len(sys.argv) > 1 else root / 'executable'
output.parent.mkdir(parents=True, exist_ok=True)
temporary = output.with_name(output.name+'.new')
with temporary.open('wb') as stream:
    stream.write(b'#!/usr/bin/env python3\n')
    with zipfile.ZipFile(stream, 'w', compression=zipfile.ZIP_DEFLATED) as archive:
        archive.writestr('__main__.py', 'from melody.cli import entrypoint\nentrypoint()\n')
        for path in sorted((root/'melody').glob('*.py')):
            archive.write(path, str(path.relative_to(root)))
os.chmod(temporary, 0o755)
os.replace(temporary, output)
